INSERT INTO "public"."trivias" ("id", "content", "publish_date", "created_at", "updated_at") VALUES
	(32, 'The Sagip Saka Act, or Republic Act No. 11321, is a Philippine law enacted in April 2019. It aims to achieve food security and boost the income of local farmers and fisherfolk by allowing national and local government agencies to purchase farm and fishery goods directly from registered cooperatives without public bidding.', '2026-08-23', '2026-08-15 13:30:48.102938+00', '2026-08-15 13:30:48.102938+00'),
	(2, 'What is the Japanese art of flower arrangement called? Ikebana', '2026-07-23', '2026-07-22 14:56:14.70057+00', '2026-07-22 14:56:50.848155+00'),
	(3, 'The Protestant Reformation was started by whom? Martin Luther', '2026-09-25', '2026-07-22 14:57:26.128654+00', '2026-07-22 14:57:26.128654+00'),
	(4, 'Which creature''s name translates as "the lizard" in Spanish? Alligator', '2026-07-25', '2026-07-22 14:58:06.297376+00', '2026-07-22 14:58:06.297376+00'),
	(6, 'What sport is Pele associated with? Soccer', '2026-07-24', '2026-07-22 14:59:14.555412+00', '2026-07-27 11:13:06.789905+00'),
	(7, 'A typical cumulus cloud has a volume of about one cubic kilometer and holds water droplets that weigh roughly 1.1 million pounds.', '2026-07-27', '2026-07-27 11:44:25.655149+00', '2026-07-27 11:44:25.655149+00'),
	(11, 'Venus is the only planet in our solar system that rotates from east to west (clockwise)', '2026-08-08', '2026-07-27 11:46:36.672426+00', '2026-07-27 11:46:36.672426+00'),
	(14, 'Trial', '2026-07-28', '2026-07-28 10:57:27.603404+00', '2026-07-28 10:57:27.603404+00'),
	(15, 'TRIALTRIALTRIALTRIALTRIALTRIALTRIALTRIALTRIAL', '2026-07-29', '2026-07-28 10:57:42.157537+00', '2026-07-29 11:49:12.954727+00'),
	(18, 'Trivia text example', '2026-07-31', '2026-07-30 18:57:15.460703+00', '2026-07-30 19:02:45.717317+00'),
	(1, 'Honey is the only food that never goes bad; archaeologists have even found edible, 3,000-year-old honey in ancient Egyptian tombs!', '2026-08-04', '2026-07-22 14:44:39.534662+00', '2026-08-04 03:40:47.236015+00'),
	(19, 'Trial Trivia', '2026-08-05', '2026-08-05 13:11:34.533261+00', '2026-08-05 13:11:34.533261+00'),
	(20, 'Trivia test', '2026-08-07', '2026-08-06 14:35:29.749798+00', '2026-08-06 14:35:29.749798+00'),
	(21, 'Trivia sample 1', '2026-08-06', '2026-08-06 14:43:10.512411+00', '2026-08-06 14:43:10.512411+00'),
	(22, 'The current Secretary of the Department of Agriculture (DA) in the Philippines is Francisco Tiu Laurel Jr., who assumed office on November 3, 2023.', '2026-08-14', '2026-08-09 03:47:46.426658+00', '2026-08-09 03:47:46.426658+00'),
	(24, 'The undisputed top aquacultural export commodity of the Philippines is seaweed (primarily Kappaphycus and Eucheuma species), which accounts for roughly 60–70% of total national aquaculture volume and stands as a major consistent fishery export. It is globally processed and exported mainly in the form of raw or semi-refined carrageenan.', '2026-08-20', '2026-08-09 03:50:26.586813+00', '2026-08-09 03:50:26.586813+00'),
	(25, 'A human sneeze can travel at a staggering speed of up to 100 miles per hour.', '2026-08-10', '2026-08-10 02:40:59.043948+00', '2026-08-10 02:40:59.043948+00'),
	(27, 'The Secretary of the Department of Agriculture (DA) in 2026 is Francisco "Kiko" Tiu Laurel Jr., who has been serving in the post since his appointment by President Ferdinand R. Marcos Jr. in November 2023.', '2026-08-16', '2026-08-15 13:28:22.141348+00', '2026-08-15 13:29:02.948214+00'),
	(23, 'The Secretary of the Department of Agriculture (DA) in 2026 is Francisco "Kiko" Tiu Laurel Jr., who has been serving in the post since his appointment by President Ferdinand R. Marcos Jr. in November 2023.', '2026-08-17', '2026-08-09 03:48:50.596543+00', '2026-08-15 13:29:11.791441+00'),
	(28, 'The current chairperson of the Senate Committee on Agriculture, Food and Agrarian Reform in the Philippines is Senator Francis “Kiko” Pangilinan.', '2026-08-18', '2026-08-15 13:28:52.777299+00', '2026-08-15 13:29:24.987557+00'),
	(29, 'The Secretary of the Department of Agriculture (DA) in 2026 is Francisco "Kiko" Tiu Laurel Jr., who has been serving in the post since his appointment by President Ferdinand R. Marcos Jr. in November 2023.', '2026-08-19', '2026-08-15 13:29:34.312888+00', '2026-08-15 13:29:34.312888+00'),
	(30, 'The undisputed top aquacultural export commodity of the Philippines is seaweed (primarily Kappaphycus and Eucheuma species), which accounts for roughly 60–70% of total national aquaculture volume and stands as a major consistent fishery export. It is globally processed and exported mainly in the form of raw or semi-refined carrageenan.', '2026-08-21', '2026-08-15 13:29:46.374231+00', '2026-08-15 13:29:46.374231+00'),
	(31, 'The Sagip Saka Act, or Republic Act No. 11321, is a Philippine law enacted in April 2019. It aims to achieve food security and boost the income of local farmers and fisherfolk by allowing national and local government agencies to purchase farm and fishery goods directly from registered cooperatives without public bidding.', '2026-08-22', '2026-08-15 13:30:35.59541+00', '2026-08-15 13:30:35.59541+00');
